// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Calculus is built on one idea: the limit. It asks what a function is approaching, not where it actually lands.","blocks":[{"t":"key","text":"lim (x→c) f(x) = L means f(x) gets as close as we like to L as x gets close to c (from both sides)."},{"t":"p","text":"The limit doesn't care what happens exactly at x = c, only nearby. f(c) might be different, or undefined."},{"t":"p","text":"A limit exists only if the left-hand limit and the right-hand limit are equal. If they differ (a jump) or the function blows up (a vertical asymptote), the limit does not exist."},{"t":"ex","problem":"Read lim (x→2) f(x) from a table: f(1.9) = 4.88, f(1.99) = 4.99, f(2.01) = 5.01, f(2.1) = 5.12","steps":["From the left, values approach 5","From the right, values approach 5"],"answer":"The limit is 5"}]},{"say":"When you can't just plug in, algebra rescues you. The goal is to get rid of the 0/0.","blocks":[{"t":"p","text":"First, try direct substitution. If you get a real number, that's the limit (for continuous functions)."},{"t":"p","text":"If substitution gives 0/0 (an indeterminate form), try:"},{"t":"list","items":["Factoring and canceling.","Multiplying by the conjugate (for square roots).","Simplifying complex fractions."]},{"t":"ex","problem":"Find lim (x→3) (x² − 9)/(x − 3)","steps":["Substituting gives 0/0","Factor: (x + 3)(x − 3)/(x − 3) = x + 3 for x ≠ 3","Substitute: 3 + 3"],"answer":"6"},{"t":"p","text":"Special limits to know: lim (x→0) sin x / x = 1 and lim (x→0) (1 − cos x)/x = 0."},{"t":"p","text":"The Squeeze Theorem: if g(x) ≤ f(x) ≤ h(x) and g and h approach the same limit, f does too."}]},{"say":"Limits also tell us about end behavior and whether a graph has any breaks. Both show up all over the exam.","blocks":[{"t":"p","text":"Limits at infinity describe horizontal asymptotes. For rational functions, compare degrees: bigger bottom → 0; equal degrees → ratio of leading coefficients; bigger top → ±∞."},{"t":"key","text":"f is continuous at x = c if f(c) is defined, lim (x→c) f(x) exists, and the limit equals f(c)."},{"t":"p","text":"Types of discontinuities: removable (a hole), jump, and infinite (vertical asymptote)."},{"t":"p","text":"Intermediate Value Theorem (IVT): if f is continuous on [a, b], then f takes every value between f(a) and f(b). For example, if f(1) = −2 and f(3) = 5, then f(c) = 0 for some c in (1, 3)."},{"t":"ex","problem":"Is f(x) = (x² − 4)/(x − 2) continuous at x = 2? How would you fix it?","steps":["f(2) is undefined, so it's not continuous","The limit is 4 (factor and cancel)"],"answer":"Removable discontinuity; define f(2) = 4"},{"t":"lab","kind":"demo","title":"Parking garage fees","aim":"A garage charges $5 for each hour or part of an hour. Explore where the cost function is discontinuous.","sets":[{"name":"t","start":1.5,"label":"Time parked (hours)","min":0.05,"max":6,"step":0.05}],"outs":[{"name":"C","expr":"5*ceil(t)","label":"Cost ($)"}],"steps":["Look at the cost just before and just after t = 2. Do the one-sided limits agree?"],"noise":0,"result":"The cost is a step function with jump discontinuities at every whole hour: the left-hand limit at t = 2 is $10 but the right-hand limit is $15, so the limit doesn't exist there.","plot":{"x":"t","y":"C"}}]}],[{"say":"The derivative measures instantaneous rate of change: the slope of a curve at one exact point.","blocks":[{"t":"p","text":"The average rate of change over [a, b] is the slope of the secant line: (f(b) − f(a)) ÷ (b − a)."},{"t":"key","text":"f′(x) = lim (h→0) [f(x + h) − f(x)] / h, the slope of the tangent line."},{"t":"ex","problem":"Use the definition to find f′(x) for f(x) = x²","steps":["[(x + h)² − x²]/h = (2xh + h²)/h","Simplify: 2x + h","Let h → 0"],"answer":"f′(x) = 2x"},{"t":"p","text":"Differentiability implies continuity, but not the reverse. A function is not differentiable at corners (like |x| at 0), cusps, vertical tangents, or discontinuities."},{"t":"lab","kind":"demo","title":"Secant slopes become a tangent","aim":"A tank drains so its volume is V(t) = 100(1 − t/10)² liters. Estimate the rate at t = 4 from secant slopes.","sets":[{"name":"hh","start":1,"label":"Interval length h (min)","min":0.01,"max":3,"step":0.01}],"outs":[{"name":"sec","expr":"(100*(1 - (4 + hh)/10)^2 - 100*(1 - 4/10)^2)/hh","label":"Secant slope (L/min)"}],"steps":["Make h smaller and smaller. What value is the slope approaching?"],"noise":0,"result":"The difference quotient [V(4 + h) − V(4)]/h approaches −12 L/min as h → 0. That limit is the derivative V′(4), the instantaneous rate at which water leaves the tank.","plot":{"x":"hh","y":"sec"}}]},{"say":"Computing limits every time would be exhausting. These rules give derivatives in seconds!","blocks":[{"t":"key","text":"Power rule: d/dx [xⁿ] = nxⁿ⁻¹."},{"t":"list","items":["Constant rule: the derivative of a constant is 0.","Constant multiple: d/dx [c·f] = c·f′.","Sum rule: differentiate term by term."]},{"t":"ex","problem":"Find f′(x) for f(x) = 4x³ − 5x + 2 − 6/x","steps":["Rewrite 6/x as 6x⁻¹","12x² − 5 + 0 + 6x⁻²"],"answer":"f′(x) = 12x² − 5 + 6/x²"},{"t":"p","text":"Rewrite roots and fractions as powers first: √x = x^(1/2), so its derivative is (1/2)x^(−1/2) = 1/(2√x)."},{"t":"p","text":"Derivatives of sin and cos: d/dx sin x = cos x, d/dx cos x = −sin x. Also d/dx eˣ = eˣ and d/dx ln x = 1/x."}]},{"say":"When functions are multiplied or divided, you need special rules. Don't just multiply the derivatives!","blocks":[{"t":"key","text":"Product rule: (fg)′ = f′g + fg′. Quotient rule: (f/g)′ = (f′g − fg′)/g²."},{"t":"p","text":"Memory trick for the quotient rule: \"low d-high minus high d-low, over the square of what's below.\""},{"t":"ex","problem":"Find d/dx [x² sin x]","steps":["f = x², f′ = 2x; g = sin x, g′ = cos x","f′g + fg′"],"answer":"2x sin x + x² cos x"},{"t":"p","text":"Use the quotient rule to get d/dx tan x = sec²x. Other trig derivatives: d/dx sec x = sec x tan x, d/dx csc x = −csc x cot x, d/dx cot x = −csc²x."},{"t":"oops","text":"(fg)′ is NOT f′g′. For x · x, f′g′ would be 1, but the derivative of x² is 2x."}]}],[{"say":"The chain rule handles functions inside functions. It's the most-used rule in all of calculus.","blocks":[{"t":"key","text":"d/dx f(g(x)) = f′(g(x)) · g′(x). Differentiate the outside, keep the inside, then multiply by the derivative of the inside."},{"t":"ex","problem":"Find d/dx (3x² + 1)⁵","steps":["Outside: 5( )⁴; inside: 3x² + 1","5(3x² + 1)⁴ · 6x"],"answer":"30x(3x² + 1)⁴"},{"t":"p","text":"More examples: d/dx sin(4x) = 4cos(4x). d/dx e^(x²) = 2x e^(x²). d/dx ln(5x + 1) = 5/(5x + 1)."},{"t":"tip","text":"Ask \"what's the last operation I'd do to evaluate this?\" That's the outside function."},{"t":"lab","kind":"demo","title":"Spreading ripples and the chain rule","aim":"A stone hits a pond and the ripple's radius grows 3 cm per second. How fast is the ripple's area growing?","sets":[{"name":"t","start":2,"label":"Time (s)","min":0,"max":10,"step":0.1}],"outs":[{"name":"r","expr":"3*t","label":"Radius (cm)"},{"name":"A","expr":"pi*r^2","label":"Area (cm²)"},{"name":"dA","expr":"2*pi*r*3","label":"dA/dt (cm²/s)"}],"steps":["Differentiate A = π(3t)² using the chain rule."],"noise":0,"result":"dA/dt = dA/dr · dr/dt = 2πr · 3. The area grows faster and faster even though the radius grows at a constant rate, because a bigger circle adds more area per centimeter.","plot":{"x":"t","y":"dA"}}]},{"say":"Some curves, like circles, can't be written as y = something. Implicit differentiation still finds their slopes.","blocks":[{"t":"p","text":"Differentiate both sides with respect to x. Every time you differentiate a y term, multiply by dy/dx (chain rule). Then solve for dy/dx."},{"t":"ex","problem":"Find dy/dx for x² + y² = 25","steps":["Differentiate: 2x + 2y(dy/dx) = 0","Solve: dy/dx = −2x/(2y)"],"answer":"dy/dx = −x/y"},{"t":"ex","problem":"Find the slope of x² + y² = 25 at (3, 4)","steps":["dy/dx = −x/y = −3/4"],"answer":"−3/4"},{"t":"p","text":"Watch for products: d/dx (xy) = y + x(dy/dx) by the product rule."}]},{"say":"Derivatives of inverse functions have a neat shortcut. And you can take derivatives of derivatives!","blocks":[{"t":"key","text":"If g is the inverse of f, then g′(x) = 1 / f′(g(x)). The slopes at matching points are reciprocals."},{"t":"ex","problem":"f(2) = 5 and f′(2) = 4. If g = f⁻¹, find g′(5).","steps":["g(5) = 2 because f(2) = 5","g′(5) = 1/f′(2)"],"answer":"1/4"},{"t":"p","text":"Inverse trig derivatives: d/dx arcsin x = 1/√(1 − x²), d/dx arctan x = 1/(1 + x²)."},{"t":"p","text":"The second derivative f″ is the derivative of f′. If position is s(t), then velocity is s′(t) and acceleration is s″(t)."}]}],[{"say":"A derivative is a rate of change, with real units. Interpreting it in context is a big part of the AP exam.","blocks":[{"t":"p","text":"If V(t) is the volume of water in liters at t minutes, then V′(5) = 3 means at t = 5, the volume is increasing at 3 liters per minute."},{"t":"key","text":"Position s(t), velocity v(t) = s′(t), acceleration a(t) = v′(t) = s″(t)."},{"t":"list","items":["The particle moves right (or up) when v > 0, left when v < 0, and is at rest when v = 0.","Speed is |v(t)|. Speed increases when v and a have the same sign, and decreases when they have opposite signs."]},{"t":"ex","problem":"s(t) = t³ − 6t². When is the particle at rest?","steps":["v(t) = 3t² − 12t = 3t(t − 4)"],"answer":"t = 0 and t = 4"}]},{"say":"Related rates problems connect how fast different quantities change. Think ladders sliding and balloons inflating.","blocks":[{"t":"p","text":"Steps:"},{"t":"list","items":["Draw a picture and name the variables.","Write an equation relating them.","Differentiate both sides with respect to time t.","Substitute known values, then solve for the unknown rate."]},{"t":"ex","problem":"A circle's radius grows at 2 cm/s. How fast is its area growing when r = 5 cm?","steps":["A = πr²","dA/dt = 2πr (dr/dt)","dA/dt = 2π(5)(2)"],"answer":"20π cm²/s"},{"t":"oops","text":"Plug in the specific values only after you differentiate. If you plug in r = 5 first, the derivative of a constant is 0."},{"t":"lab","kind":"demo","title":"Sliding ladder","aim":"A 5 m ladder slides away from a wall at 1 m/s at its base. How fast is the top sliding down?","sets":[{"name":"x","start":3,"label":"Base distance from the wall (m)","min":0.2,"max":4.9,"step":0.1}],"outs":[{"name":"y","expr":"sqrt(25 - x^2)","label":"Height of the top (m)"},{"name":"dy","expr":"-x*1/y","label":"dy/dt (m/s)"}],"steps":["Differentiate x² + y² = 25 with respect to time and solve for dy/dt."],"noise":0,"result":"2x(dx/dt) + 2y(dy/dt) = 0 gives dy/dt = −x(dx/dt)/y. At x = 3 the top falls at 0.75 m/s, and it speeds up dramatically as the ladder nears the ground.","plot":{"x":"x","y":"dy"}}]},{"say":"The tangent line makes a great approximation near a point. And L'Hospital's rule finds tricky limits fast.","blocks":[{"t":"p","text":"Local linear approximation: near x = a, f(x) ≈ f(a) + f′(a)(x − a). This is the tangent line."},{"t":"ex","problem":"Approximate √4.1 using f(x) = √x at a = 4","steps":["f(4) = 2, f′(x) = 1/(2√x), f′(4) = 1/4","f(4.1) ≈ 2 + (1/4)(0.1)"],"answer":"about 2.025"},{"t":"p","text":"If f is concave up, the tangent line approximation is an underestimate; if concave down, an overestimate."},{"t":"key","text":"L'Hospital's rule: if a limit gives 0/0 or ∞/∞, then lim f/g = lim f′/g′ (if that limit exists)."},{"t":"ex","problem":"lim (x→0) (eˣ − 1)/x","steps":["0/0, so differentiate top and bottom: eˣ/1"],"answer":"1"}]}],[{"say":"The Mean Value Theorem guarantees that at some moment, your instant speed equals your average speed.","blocks":[{"t":"key","text":"Mean Value Theorem: if f is continuous on [a, b] and differentiable on (a, b), then f′(c) = (f(b) − f(a))/(b − a) for some c in (a, b)."},{"t":"p","text":"Extreme Value Theorem: a continuous function on a closed interval [a, b] has both an absolute maximum and an absolute minimum."},{"t":"p","text":"Critical points are where f′(x) = 0 or f′ is undefined. Absolute extrema on [a, b] happen at critical points or endpoints."},{"t":"ex","problem":"Find the absolute max of f(x) = x³ − 3x on [0, 2]","steps":["f′(x) = 3x² − 3 = 0 at x = 1","Check: f(0) = 0, f(1) = −2, f(2) = 2"],"answer":"Absolute max 2 at x = 2 (absolute min −2 at x = 1)"}]},{"say":"The first and second derivatives tell the whole story of a graph's shape.","blocks":[{"t":"list","items":["f′ > 0: f is increasing. f′ < 0: f is decreasing.","First derivative test: if f′ changes from + to −, f has a local max; from − to +, a local min.","f″ > 0: f is concave up (cup). f″ < 0: concave down (cap).","An inflection point is where concavity changes (f″ changes sign)."]},{"t":"key","text":"Second derivative test: if f′(c) = 0 and f″(c) > 0, local min; if f″(c) < 0, local max."},{"t":"ex","problem":"f(x) = x³ − 3x². Find local extrema and the inflection point.","steps":["f′ = 3x² − 6x = 3x(x − 2): zero at 0 and 2","f″ = 6x − 6: f″(0) = −6 (max), f″(2) = 6 (min)","f″ = 0 at x = 1, and f″ changes sign there"],"answer":"local max at x = 0, local min at x = 2, inflection at x = 1"}]},{"say":"Optimization finds the biggest or smallest possible value: the most area, the least cost, the shortest path.","blocks":[{"t":"p","text":"Steps:"},{"t":"list","items":["Write a formula for the quantity to maximize or minimize.","Use a constraint to write it in one variable.","Find critical points, and check endpoints of the realistic domain.","Justify that it's a max or min (first or second derivative test)."]},{"t":"ex","problem":"You have 100 m of fence for a rectangular pen. What dimensions give the most area?","steps":["Perimeter: 2x + 2y = 100, so y = 50 − x","Area: A = x(50 − x) = 50x − x²","A′ = 50 − 2x = 0, so x = 25; A″ = −2 < 0 (max)"],"answer":"25 m by 25 m, area 625 m²"},{"t":"tip","text":"Always answer the question that was asked: dimensions, maximum value or location."},{"t":"lab","kind":"demo","title":"Fencing a riverside field","aim":"A farmer has 200 m of fence for three sides of a rectangle along a straight river. Maximize the area.","sets":[{"name":"x","start":30,"label":"Side perpendicular to the river (m)","min":1,"max":99,"step":1}],"outs":[{"name":"A","expr":"x*(200 - 2*x)","label":"Area (m²)"},{"name":"dA","expr":"200 - 4*x","label":"dA/dx"}],"steps":["Set A′(x) = 200 − 4x = 0. Check that it's a maximum."],"noise":0,"result":"A′ = 0 at x = 50 m, and A″ = −4 < 0 confirms a maximum: 50 m × 100 m = 5,000 m². The derivative is positive before 50 and negative after.","plot":{"x":"x","y":"A"}}]}],[{"say":"Integration adds up tiny pieces to find a total. It starts with rectangles under a curve.","blocks":[{"t":"p","text":"If a rate is constant, total change = rate × time. If the rate varies, approximate by splitting time into pieces and adding rate × width for each: a Riemann sum."},{"t":"list","items":["Left, right and midpoint Riemann sums use different heights for each rectangle.","The trapezoidal rule averages left and right sums.","For an increasing function, a left sum underestimates and a right sum overestimates."]},{"t":"key","text":"The definite integral ∫ from a to b of f(x) dx is the limit of Riemann sums as the rectangles get infinitely thin. It gives the net (signed) area."},{"t":"p","text":"Area below the x-axis counts as negative."},{"t":"lab","kind":"demo","title":"Riemann sums for area","aim":"Estimate the area under y = x² from 0 to 3 with n rectangles. The exact area is 9.","sets":[{"name":"n","start":4,"label":"Number of rectangles","min":1,"max":100,"step":1}],"outs":[{"name":"L","expr":"27/n^3*(n - 1)*n*(2*n - 1)/6","label":"Left sum"},{"name":"Rt","expr":"27/n^3*n*(n + 1)*(2*n + 1)/6","label":"Right sum"},{"name":"err","expr":"Rt - 9","label":"Right sum error"}],"steps":["Why is the left sum always too small and the right sum too big here?"],"noise":0,"result":"For an increasing function, left sums underestimate and right sums overestimate. As n → ∞ both approach 9, which is the definite integral ∫₀³ x² dx.","plot":{"x":"n","y":"L"}}]},{"say":"The Fundamental Theorem connects derivatives and integrals. It's the most important theorem in calculus.","blocks":[{"t":"key","text":"FTC Part 2: ∫ from a to b of f(x) dx = F(b) − F(a), where F is any antiderivative of f."},{"t":"p","text":"FTC Part 1: d/dx ∫ from a to x of f(t) dt = f(x). Accumulating a function, then differentiating, gives the function back."},{"t":"ex","problem":"Evaluate ∫ from 1 to 3 of 2x dx","steps":["An antiderivative of 2x is x²","F(3) − F(1) = 9 − 1"],"answer":"8"},{"t":"ex","problem":"Find d/dx ∫ from 0 to x² of cos t dt","steps":["FTC 1 with the chain rule: cos(x²) · 2x"],"answer":"2x cos(x²)"},{"t":"p","text":"Properties: ∫ from a to a = 0; reversing the limits changes the sign; integrals over adjacent intervals add."}]},{"say":"Finding antiderivatives is differentiation in reverse. And u-substitution undoes the chain rule.","blocks":[{"t":"p","text":"Basic antiderivatives (always add + C for indefinite integrals):"},{"t":"list","items":["∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1)","∫ 1/x dx = ln|x| + C","∫ eˣ dx = eˣ + C","∫ cos x dx = sin x + C and ∫ sin x dx = −cos x + C"]},{"t":"key","text":"u-substitution: choose u as the inside function, find du, and rewrite the whole integral in terms of u."},{"t":"ex","problem":"Find ∫ 2x(x² + 1)⁴ dx","steps":["Let u = x² + 1, so du = 2x dx","∫ u⁴ du = u⁵/5 + C"],"answer":"(x² + 1)⁵/5 + C"},{"t":"p","text":"For definite integrals with u-substitution, change the limits to u-values too."}]}],[{"say":"A differential equation describes how something changes. Its solution is a function, not a number.","blocks":[{"t":"p","text":"A differential equation relates a function to its derivatives, like dy/dx = 2x. A solution is a function that makes it true, like y = x² + C."},{"t":"p","text":"To verify a solution, differentiate it and substitute into the equation."},{"t":"p","text":"A slope field draws a tiny line segment with slope dy/dx at many points. Solution curves follow the segments like a current."},{"t":"ex","problem":"For dy/dx = x + y, what is the slope at (1, 2)?","steps":["Substitute: 1 + 2"],"answer":"slope 3"},{"t":"tip","text":"If dy/dx depends only on x, the slope segments are the same along each vertical column. If it depends only on y, they're the same along each horizontal row."}]},{"say":"Separation of variables solves many differential equations: move all the y's to one side and x's to the other, then integrate.","blocks":[{"t":"p","text":"Steps: separate (y terms with dy, x terms with dx), integrate both sides, add C, use the initial condition to find C, then solve for y."},{"t":"ex","problem":"Solve dy/dx = xy with y(0) = 3","steps":["Separate: dy/y = x dx","Integrate: ln|y| = x²/2 + C","Solve: y = Ae^(x²/2); y(0) = 3 gives A = 3"],"answer":"y = 3e^(x²/2)"},{"t":"key","text":"dy/dt = ky has solution y = y₀e^(kt): exponential growth if k > 0, decay if k < 0."},{"t":"p","text":"This models populations, radioactive decay, Newton's law of cooling and continuously compounded interest."},{"t":"lab","kind":"demo","title":"Medicine leaving the body","aim":"A drug is eliminated at a rate proportional to the amount present: dA/dt = −kA. Start with 200 mg.","sets":[{"name":"t","start":4,"label":"Time (hours)","min":0,"max":24,"step":0.5},{"name":"k","start":0.2,"label":"Elimination constant k","min":0.05,"max":0.6,"step":0.05}],"outs":[{"name":"A","expr":"200*exp(-k*t)","label":"Amount left (mg)"},{"name":"half","expr":"ln(2)/k","label":"Half-life (hours)"}],"steps":["Separate variables to solve dA/A = −k dt."],"noise":0,"result":"Separation of variables gives A = 200e^(−kt). The half-life ln 2/k doesn't depend on the dose, which is why medicines are taken at regular intervals.","plot":{"x":"t","y":"A"}}]}],[{"say":"Integrals answer real questions: average temperature, total distance traveled, and more.","blocks":[{"t":"key","text":"Average value of f on [a, b] = (1/(b − a)) ∫ from a to b of f(x) dx."},{"t":"p","text":"For motion with velocity v(t):"},{"t":"list","items":["Displacement = ∫ v(t) dt (net change in position).","Total distance = ∫ |v(t)| dt (always positive).","Position at time t: s(t) = s(0) + ∫ from 0 to t of v(u) du."]},{"t":"ex","problem":"v(t) = t − 2 on [0, 4]. Find displacement and total distance.","steps":["Displacement: ∫ (t − 2) dt from 0 to 4 = [t²/2 − 2t] = 8 − 8 = 0","Distance: area from 0 to 2 is 2, from 2 to 4 is 2"],"answer":"displacement 0, total distance 4"},{"t":"p","text":"More generally, ∫ of a rate gives the net change in the quantity: ∫ from a to b of R′(t) dt = R(b) − R(a)."}]},{"say":"To find the area between two curves, integrate the top function minus the bottom function.","blocks":[{"t":"key","text":"Area = ∫ from a to b of [top(x) − bottom(x)] dx."},{"t":"p","text":"Find where the curves intersect to get the limits of integration. If the curves cross in the middle, split the integral."},{"t":"ex","problem":"Find the area between y = x and y = x² from x = 0 to 1","steps":["On [0, 1], x ≥ x², so top = x","∫ (x − x²) dx = [x²/2 − x³/3] from 0 to 1"],"answer":"1/2 − 1/3 = 1/6"},{"t":"p","text":"Sometimes it's easier to integrate with respect to y: Area = ∫ [right(y) − left(y)] dy."}]},{"say":"Spin a region around an axis or stack shapes on it, and integration finds the volume.","blocks":[{"t":"p","text":"Volume by cross sections: V = ∫ A(x) dx, where A(x) is the area of each cross section (squares, semicircles, triangles…)."},{"t":"key","text":"Disc method: V = π ∫ [R(x)]² dx. Washer method: V = π ∫ ([R(x)]² − [r(x)]²) dx, with outer radius R and inner radius r."},{"t":"ex","problem":"Rotate y = √x from x = 0 to 4 about the x-axis. Find the volume.","steps":["Disc radius R = √x","V = π ∫ from 0 to 4 of x dx = π[x²/2]"],"answer":"8π"},{"t":"p","text":"When rotating about a line other than an axis, measure radii from that line: about y = −1, R = f(x) + 1."},{"t":"lab","kind":"demo","title":"Filling a parabolic glass","aim":"A glass is shaped by spinning x = √y around the y-axis. How much liquid does it hold up to height h?","sets":[{"name":"h","start":4,"label":"Liquid height (cm)","min":0,"max":10,"step":0.1}],"outs":[{"name":"V","expr":"pi*h^2/2","label":"Volume (cm³)"},{"name":"dV","expr":"pi*h","label":"dV/dh (cm³ per cm)"}],"steps":["Use the disk method: V = ∫₀ʰ π(√y)² dy."],"noise":0,"result":"V = π∫₀ʰ y dy = πh²/2. Filling to half the height holds only a quarter of the volume, because the glass widens toward the top.","plot":{"x":"h","y":"V"}}]}]];
export default text;
